import io
import os
from collections import OrderedDict

import numpy as np
import pandas as pd
import pytest

from darts import TimeSeries, metrics
from darts.models import NaiveSeasonal
from darts.models.forecasting.forecasting_model import (
    ForecastingModel,
    FutureCovariatesLocalForecastingModel,
    GlobalForecastingModel,
    LocalForecastingModel,
    TransferableFutureCovariatesLocalForecastingModel,
)
from darts.utils.serialization.base import UnpicklingError


def make_series(values=None, start=0, freq=1):
    if values is None:
        values = np.arange(10.0)
    values = np.asarray(values, dtype=float)
    if values.ndim == 1:
        values = values[:, None]
    index = pd.RangeIndex(start, start + len(values), freq)
    return TimeSeries.from_times_and_values(index, values, freq=freq)


def make_datetime_series(values=None):
    if values is None:
        values = np.arange(8.0)
    values = np.asarray(values, dtype=float).reshape(-1, 1)
    return TimeSeries.from_times_and_values(
        pd.date_range("2020-01-01", periods=len(values), freq="D"), values
    )


def add_static_covariates(series, value=1.0):
    static = pd.DataFrame({"static": [value]}, index=series.components)
    return series.with_static_covariates(static)


class ConstantLocalForecastingModel(LocalForecastingModel):
    def __init__(self, add_encoders=None, value=0.0, min_train_length=None):
        super().__init__(
            add_encoders=add_encoders, min_train_length=min_train_length
        )
        self.value = value

    @property
    def supports_multivariate(self):
        return False

    def fit(self, series, verbose=None):
        super().fit(series, verbose=verbose)
        return self

    def predict(
        self,
        n,
        num_samples=1,
        verbose=None,
        show_warnings=True,
        random_state=None,
    ):
        return self._build_forecast_series(np.full((n, 1), self.value))


class FittedConstantLocalForecastingModel(ConstantLocalForecastingModel):
    def __init__(self, add_encoders=None, value=0.0, min_train_length=None):
        super().__init__(
            add_encoders=add_encoders,
            value=value,
            min_train_length=min_train_length,
        )
        self.fitted_values = None

    def fit(self, series, verbose=None):
        super().fit(series, verbose=verbose)
        self.fitted_values = np.full((len(series), 1), self.value)
        return self


class MissingAddEncodersModel(ConstantLocalForecastingModel):
    def __init__(self, value=0.0):
        # Intentionally bypass LocalForecastingModel's add_encoders forwarding.
        ForecastingModel.__init__(self)
        self.value = value


class ConstantGlobalForecastingModel(GlobalForecastingModel):
    def __init__(
        self,
        add_encoders=None,
        value=0.0,
        output_chunk_length=1,
        covariates=False,
        static_covariates=False,
        likelihood=False,
    ):
        super().__init__(add_encoders=add_encoders)
        self.value = value
        self._output_chunk_length = output_chunk_length
        self._covariates = covariates
        self._static_covariates = static_covariates
        self._likelihood = likelihood

    @property
    def supports_multivariate(self):
        return True

    @property
    def supports_past_covariates(self):
        return self._covariates

    @property
    def supports_future_covariates(self):
        return self._covariates

    @property
    def supports_static_covariates(self):
        return self._static_covariates

    @property
    def considers_static_covariates(self):
        return self._static_covariates

    @property
    def supports_likelihood_parameter_prediction(self):
        return self._likelihood

    @property
    def supports_probabilistic_prediction(self):
        return self._likelihood

    @property
    def output_chunk_length(self):
        return self._output_chunk_length

    @property
    def min_train_samples(self):
        return 1

    @property
    def _target_window_lengths(self):
        return 1, self._output_chunk_length

    @property
    def extreme_lags(self):
        if self._covariates:
            return (-1, self._output_chunk_length - 1, -1, 0, 0, 0, 0)
        return (-1, self._output_chunk_length - 1, None, None, None, None, 0)

    @property
    def _model_encoder_settings(self):
        return (
            1,
            self._output_chunk_length,
            self._covariates,
            self._covariates,
            None,
            None,
        )

    def fit(
        self,
        series,
        past_covariates=None,
        future_covariates=None,
        verbose=None,
    ):
        super().fit(
            series,
            past_covariates=past_covariates,
            future_covariates=future_covariates,
            verbose=verbose,
        )
        return self

    def predict(
        self,
        n,
        series=None,
        past_covariates=None,
        future_covariates=None,
        num_samples=1,
        verbose=None,
        predict_likelihood_parameters=False,
        show_warnings=True,
        random_state=None,
    ):
        super().predict(
            n,
            series=series,
            past_covariates=past_covariates,
            future_covariates=future_covariates,
            num_samples=num_samples,
            verbose=verbose,
            predict_likelihood_parameters=predict_likelihood_parameters,
            show_warnings=show_warnings,
            random_state=random_state,
        )
        input_series = series if series is not None else self.training_series
        if isinstance(input_series, (list, tuple)):
            return [
                self._build_forecast_series(
                    np.full((n, 1), self.value), input_series=s
                )
                for s in input_series
            ]
        return self._build_forecast_series(
            np.full((n, 1), self.value), input_series=input_series
        )


class ShiftedConstantGlobalForecastingModel(ConstantGlobalForecastingModel):
    @property
    def output_chunk_shift(self):
        return 1


class ConstantFutureCovariatesLocalForecastingModel(
    FutureCovariatesLocalForecastingModel
):
    def __init__(self, add_encoders=None, min_train_length=None):
        super().__init__(
            add_encoders=add_encoders, min_train_length=min_train_length
        )
        self.fit_future_covariates = None
        self.last_future_covariates = None

    @property
    def supports_multivariate(self):
        return True

    def _fit(self, series, future_covariates=None, verbose=None):
        self.fit_future_covariates = future_covariates
        return self

    def _predict(
        self,
        n,
        future_covariates=None,
        num_samples=1,
        predict_likelihood_parameters=False,
        verbose=False,
        random_state=None,
        **kwargs,
    ):
        self.last_future_covariates = future_covariates
        return self._build_forecast_series(
            np.zeros((n, self.training_series.width))
        )


class ConstantTransferableForecastingModel(
    TransferableFutureCovariatesLocalForecastingModel
):
    def __init__(self, add_encoders=None):
        super().__init__(add_encoders=add_encoders)
        self.prediction_inputs = None

    @property
    def supports_multivariate(self):
        return True

    def _fit(self, series, future_covariates=None, verbose=None):
        return self

    def _predict(
        self,
        n,
        series=None,
        historic_future_covariates=None,
        future_covariates=None,
        num_samples=1,
        predict_likelihood_parameters=False,
        verbose=False,
        random_state=None,
    ):
        self.prediction_inputs = {
            "series": series,
            "historic": historic_future_covariates,
            "future": future_covariates,
        }
        input_series = series if series is not None else self.training_series
        return self._build_forecast_series(
            np.zeros((n, input_series.width)), input_series=input_series
        )


class NestedParameterModel(ConstantLocalForecastingModel):
    def __init__(self, add_encoders=None, outer_value=1.0):
        self.inner = ConstantLocalForecastingModel(value=2.5)
        super().__init__(add_encoders=add_encoders, value=outer_value)


