def test_future_covariate_encoders_generate_train_and_predict_series(datetime_series):
    model = ConstantFutureCovariatesLocalForecastingModel(
        add_encoders={"datetime_attribute": {"future": ["year", "month"]}}
    ).fit(datetime_series)

    _, fit_covs = model.generate_fit_encodings(datetime_series)
    assert len(fit_covs) == len(datetime_series)
    assert fit_covs.n_components == 2
    assert all(name.startswith("darts_enc_fc_dta_") for name in fit_covs.components)

    _, pred_covs = model.generate_predict_encodings(3, datetime_series)
    assert len(pred_covs) == 3
    assert pred_covs.start_time() == datetime_series.end_time() + datetime_series.freq

    _, both_covs = model.generate_fit_predict_encodings(3, datetime_series)
    assert len(both_covs) == len(datetime_series) + 3


